// Ambient global injected by vite.config.ts's `define` at build time — a
// human-readable timestamp of when this bundle was produced. Surfaced in
// the mobile chat header so an installed PWA (which doesn't reload itself
// automatically the way a browser tab does) can be visually confirmed to
// be running the build you think it's running.
declare const __HERMES_BUILD_TIME__: string;
